param([string]$LauncherPath=(Join-Path $PSScriptRoot '..\launch_paper_text_multiseed_smoke_r9.ps1'),[ValidateSet('refused','accepted')][string]$Expected='refused')
$ErrorActionPreference='Stop';$t=$null;$e=$null;$a=[Management.Automation.Language.Parser]::ParseFile((Resolve-Path $LauncherPath),[ref]$t,[ref]$e);if($e.Count){throw 'r9 launcher does not parse'};$f=$a.Find({param($n)$n -is [Management.Automation.Language.FunctionDefinitionAst] -and $n.Name -eq 'Get-StableAcPowerFacts'},$true);Invoke-Expression $f.Extent.Text;$accepted=$false;$reason=$null;try{Get-StableAcPowerFacts|Out-Null;$accepted=$true}catch{$reason=$_.Exception.Message};if(($Expected -eq 'refused') -ne (-not $accepted)){throw 'live power expectation failed'};[pscustomobject]@{status='pass';accepted=$accepted;refusal=$reason;pilot_launched=$false}|ConvertTo-Json -Compress
